@Composable
fun HistoryScreen(viewModel: MainViewModel, paddingValues: PaddingValues) {
    val workouts by viewModel.allWorkouts.collectAsState()
    val completedWorkouts = workouts.filter { it.workout.isCompleted }.sortedByDescending { it.workout.dateMillis }

    // Calculates lifetime stats
    val totalWorkouts = completedWorkouts.size
    var totalSets = 0
    var totalReps = 0
    completedWorkouts.forEach { w ->
        w.exercises.forEach { e ->
            totalSets += e.sets.size
            e.sets.forEach { set ->
                totalReps += set.reps ?: 0
            }
        }
    }

    Surface(
        modifier = Modifier.fillMaxSize().padding(paddingValues),
        color = Color(0xFFF8FAFC)
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(
                    brush = Brush.radialGradient(
                        colors = listOf(
                            MaterialTheme.colorScheme.tertiary.copy(alpha = 0.3f),
                            Color(0xFFF8FAFC)
                        ),
                        radius = 1500f
                    )
                )
        ) {
            if (completedWorkouts.isEmpty()) {
                Box(modifier = Modifier.fillMaxSize().padding(32.dp), contentAlignment = Alignment.Center) {
                    Text("Your training timeline is empty.", color = MaterialTheme.colorScheme.onSurfaceVariant, fontSize = 18.sp)
                }
            } else {
                LazyColumn(
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = PaddingValues(start = 24.dp, end = 24.dp, top = 32.dp, bottom = 120.dp),
                    verticalArrangement = Arrangement.spacedBy(24.dp)
                ) {
                    item {
                        Text("DASHBOARD", style = MaterialTheme.typography.labelLarge, color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold, letterSpacing = 2.sp)
                        Spacer(modifier = Modifier.height(8.dp))
                        Text("Performance", style = MaterialTheme.typography.headlineLarge, fontWeight = FontWeight.Light, color = MaterialTheme.colorScheme.onBackground)
                        Spacer(modifier = Modifier.height(16.dp))

                        // Lifetime Stats Row
                        Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                            StatCard(modifier = Modifier.weight(1f), value = totalWorkouts.toString(), label = "Workouts")
                            StatCard(modifier = Modifier.weight(1f), value = totalSets.toString(), label = "Sets")
                            StatCard(modifier = Modifier.weight(1f), value = totalReps.toString(), label = "Reps")
                        }
                    }

                    item {
                        WeeklyActivityChart(completedWorkouts)
                    }

                    item {
                        DistributionCard(completedWorkouts)
                    }

                    item {
                        Spacer(modifier = Modifier.height(16.dp))
                        Text("TIMELINE", style = MaterialTheme.typography.labelLarge, color = MaterialTheme.colorScheme.primary, fontWeight = FontWeight.Bold, letterSpacing = 2.sp)
                    }

                    items(completedWorkouts) { workout ->
                        WorkoutHistoryCard(workout = workout, onDelete = { viewModel.deleteWorkout(workout.workout) })
                    }
                }
            }
        }
    }
}

